scripts["defeat-replacement"] = [
  (c) => {
    const p = source(c);
    if (!["field", "legends"].includes(p.zone)) {
      c.j.vars.replacement = [];
      return;
    }
    const dead = gears(c.g, p.id).filter(
      (x) => x.cardId === "deadman-transmitter"
    );
    const jackies = c.g.pieces.filter(
      (x) => x.controller === p.controller && x.id !== p.id && x.cardId === "jackie-welles-mama-s-favorite" && (x.zone === "field" || x.zone === "legends" && x.faceUp) && resources(c.g, p.controller).length >= 1
    );
    const opts = [...dead, ...jackies].map((x) => ({
      id: x.id,
      label: card(x.cardId).nameFull + " replaces this defeat"
    }));
    if (!dead.length)
      opts.push({ id: "none", label: "Allow the original defeat" });
    return {
      player: p.controller,
      label: "Choose a defeat replacement",
      options: opts,
      min: 1,
      max: 1,
      key: "replacement"
    };
  },
  (c) => {
    const chosenId = selected(c.j, "replacement")[0];
    const chosen2 = chosenId && chosenId !== "none" ? piece(c.g, chosenId) : void 0;
    if (chosen2?.cardId === "jackie-welles-mama-s-favorite")
      pay(c.g, c.j.controller, 1);
  },
  (c) => {
    const id = selected(c.j, "replacement")[0];
    if (!id) return;
    defeat(
      c.g,
      id === "none" ? source(c) : piece(c.g, id),
      c.j.event.actor,
      true
    );
  }
];
